using System.Collections.Generic;

namespace TAOM.Features.TroopProgression;

// Volunteer recruitment pool for Anduin Vale, the Beorning and Woodmen realm of the upper Anduin
// (troops generated by tools/generate_anduinvale_troops.py). The data half of
// VolunteerRecruitmentService, registered by the static ctor in the core file. Lookup priority:
// conditional > settlement > clan > culture (troops.md).
public partial class VolunteerRecruitmentService
{
    private static void InitializeAnduinValeCulture()
    {
        // Two roots reach the whole tree: the Levy heads the axe line, and the Beorning Youth
        // heads the Vale riders and the bear-wardens. Levy-heavy, as Cardolan's.
        CultureMap["anduinvale"] = new List<VolunteerChance>
        {
            new VolunteerChance("anduinvale_levy", 6),
            new VolunteerChance("anduinvale_beorning_youth", 2)
        };
    }
}
